// Deferred browser-API access via useEffect — no hydration mismatch
'use client'
import { useState, useEffect } from 'react'
export default function WindowSize() {
  const [width, setWidth] = useState(0)  // safe initial value for SSR
  useEffect(() => {
    setWidth(window.innerWidth)  // runs only after hydration
  }, [])
  return <div>Width: {width}</div>
}

// Stable client-generated ID using useId — consistent across server and client
'use client'
import { useId } from 'react'
export default function Field({ label }) {
  const id = useId()  // deterministic, consistent between server and client
  return <><label htmlFor={id}>{label}</label><input id={id} /></>
}

// SSR-incompatible component excluded from hydration entirely
import dynamic from 'next/dynamic'
const HeavyChart = dynamic(() => import('./heavy-chart'), { ssr: false })
export default function Dashboard() {
  return <HeavyChart />  // not SSR'd, not hydrated on first load
}

// suppressHydrationWarning for intentional server/client difference
export default function LastUpdated() {
  return (
    <time suppressHydrationWarning dateTime={new Date().toISOString()}>
      {new Date().toLocaleDateString()}
    </time>
  )
}

