// Math.random() in render — different on server and client
'use client'
export default function Card() {
  const id = Math.random()  // MISMATCH: different values each render
  return <div id={id}>Content</div>
}

// typeof window check during render — guaranteed mismatch
'use client'
export default function Component() {
  const isClient = typeof window !== 'undefined'  // false on server, true on client
  return <div>{isClient ? 'Browser' : 'Server'}</div>  // MISMATCH
}

// localStorage access during render — throws on server
'use client'
export default function Settings() {
  const theme = localStorage.getItem('theme')  // ReferenceError on server
  return <div className={theme}>Settings</div>
}

// Direct Date rendering — timezone mismatch between server and client
'use client'
export default function Timestamp() {
  return <span>{new Date().toLocaleTimeString()}</span>  // MISMATCH: server ≠ client time
}
